using System.Text;
using System.Text.Json;
using DotReticulum.Transport;

namespace NomadNet.Tests;

// Generated by executing actual primary constructors at f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2.
// GenerateNomadNetConfigVectors.py records raw source hashes and process observation details.
[Trait("Category", "Unit")]
public sealed class NomadNetConfigTests
{
    [Fact]
    public void CoreSettingsMatchActualPrimaryConstructorObservations()
    {
        using var fixture = JsonDocument.Parse(typeof(NomadNetConfigTests).Assembly
            .GetManifestResourceStream("NomadNet.Tests.NomadNetConfigVectors.json")!);
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", fixture.RootElement.GetProperty("commit").GetString());
        foreach (var vector in fixture.RootElement.GetProperty("vectors").EnumerateArray())
        {
            var imported = NomadNetConfigImport.Parse(vector.GetProperty("input").GetString()!);
            Assert.Empty(imported.UnsupportedKeys);
            var actual = imported.Settings;
            var expected = vector.GetProperty("observed");
            Assert.Equal(expected.GetProperty("compose_in_markdown").GetBoolean(), actual.ComposeInMarkdown);
            Assert.Equal(expected.GetProperty("rrc_render_markdown").GetBoolean(), actual.RrcRenderMarkdown);
            Assert.Equal(expected.GetProperty("rrc_render_micron").GetBoolean(), actual.RrcRenderMicron);
            Assert.Equal(expected.GetProperty("enable_client").GetBoolean(), actual.EnableClient);
            Assert.Equal(expected.GetProperty("client_announce_at_start").GetBoolean(), actual.ClientAnnounceAtStart);
            Assert.Equal(expected.GetProperty("client_announce_interval").GetInt32(), actual.ClientAnnounceIntervalMinutes * 60);
            Assert.True(expected.GetProperty("client_delivery_registered").GetBoolean());
            Assert.Equal(expected.GetProperty("enable_node").GetBoolean(), actual.EnableNode);
            Assert.Equal(expected.GetProperty("node_name").GetString(), actual.NodeName);
            Assert.Equal(expected.GetProperty("announce_interval").GetInt32(), actual.NodeAnnounceIntervalMinutes);
            Assert.Equal(expected.GetProperty("node_announce_at_start").GetBoolean(), actual.NodeAnnounceAtStart);
            Assert.Equal(expected.GetProperty("page_refresh_interval").GetDouble(), actual.NodePageRefreshIntervalMinutes);
            Assert.Equal(expected.GetProperty("file_refresh_interval").GetDouble(), actual.NodeFileRefreshIntervalMinutes);
            Assert.Equal(expected.GetProperty("periodic_lxmf_sync").GetBoolean(), actual.PeriodicLxmfSync);
            Assert.Equal(expected.GetProperty("lxmf_sync_interval").GetInt32(), actual.LxmfSyncIntervalMinutes * 60);
            Assert.Equal(expected.GetProperty("lxmf_sync_limit").ValueKind == JsonValueKind.Null ? 0 :
                expected.GetProperty("lxmf_sync_limit").GetInt32(), actual.LxmfSyncLimit);
            Assert.Equal(expected.GetProperty("try_propagation_on_send_fail").GetBoolean(), actual.TryPropagationOnSendFail);
            Assert.Equal(expected.GetProperty("accept_invalid_stamps").GetBoolean(), actual.AcceptInvalidStamps);
            var cost = expected.GetProperty("required_stamp_cost");
            Assert.Equal(cost.ValueKind == JsonValueKind.Null ? null : (int?)cost.GetInt32(), actual.InboundStampCost);
            Assert.Equal((int)(expected.GetProperty("max_accepted_size").GetDouble() * 1000), actual.DeliveryTransferLimitBytes);
            Assert.False(actual.EnablePropagation);
        }
    }

    [Fact]
    public void QuotesCommentsListsAndUnsupportedKeysAreUnambiguous()
    {
        var result = NomadNetConfigImport.Parse("""
            # Public generated configuration
            [node] # section comment
            enable_node = yes
            disable_propagation = no
            node_name = 'Equals = # Hash' # outside comment
            pages_path = 'custom pages'
            files_path = public-files
            [client]
            downloads_path = ~/Downloads
            [textui]
            image_loading = yes
            [printing]
            print_from = trusted, everywhere
            """);
        Assert.True(result.Settings.EnablePropagation);
        Assert.Equal("Equals = # Hash", result.Settings.NodeName);
        Assert.Equal("custom pages", result.Settings.PagesPath);
        Assert.Equal("public-files", result.Settings.FilesPath);
        Assert.Equal(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads"),
            result.Settings.DownloadsPath);
        Assert.Equal(["printing.print_from", "textui.image_loading"], result.UnsupportedKeys);
    }

    [Theory]
    [InlineData("[node]\nenable_node=perhaps")]
    [InlineData("[client]\nmax_accepted_size=NaN")]
    [InlineData("[client]\nmax_accepted_size=999999999")]
    [InlineData("[client]\nrequired_stamp_cost=not-integer")]
    [InlineData("[node]\nnode_name='unterminated")]
    [InlineData("[node]\nenable_node=yes\nenable_node=no")]
    [InlineData("[node]\n[node]")]
    [InlineData("[[nested]]")]
    [InlineData("enable_node=yes")]
    [InlineData("[node]\nnode_name=one,two")]
    [InlineData("[client]\ndownloads_path=~another-user/Downloads")]
    public void AmbiguousOrMalformedConfigurationFailsExplicitly(string text) =>
        Assert.Throws<InvalidDataException>(() => NomadNetConfigImport.Parse(text));
}

[Trait("Category", "Integration")]
public sealed class NomadNetConfigImportTests
{
    [Fact]
    public async Task ImportCreatesAtomicProfilePreservesSourceAndRejectsOccupiedOrCanceledTargets()
    {
        var root = CreateDirectory();
        try
        {
            var source = Path.Combine(root, "upstream-config");
            const string text = "[client]\nrequired_stamp_cost=13\n[node]\nenable_node=yes\ndisable_propagation=yes\n";
            await File.WriteAllTextAsync(source, text);
            var target = Path.Combine(root, "profile");
            await NomadNetConfigImport.ImportAsync(source, target + Path.DirectorySeparatorChar);
            var settings = await NomadNetSettings.OpenAsync(target);
            Assert.Equal(13, settings.InboundStampCost);
            Assert.True(settings.EnableNode);
            Assert.False(settings.AcceptInvalidStamps);
            Assert.Empty(await (await NomadNetStore.OpenAsync(target)).MessagesAsync());
            Assert.Equal(text, await File.ReadAllTextAsync(source));
            await Assert.ThrowsAsync<IOException>(() => NomadNetConfigImport.ImportAsync(source, target));
            using var canceled = new CancellationTokenSource();
            canceled.Cancel();
            var canceledTarget = Path.Combine(root, "canceled");
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
                NomadNetConfigImport.ImportAsync(source, canceledTarget, canceled.Token));
            Assert.False(Directory.Exists(canceledTarget));
            await File.WriteAllTextAsync(source, "[node]\nnode_name=" + new string('x', 81));
            var invalid = Path.Combine(root, "invalid");
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetConfigImport.ImportAsync(source, invalid));
            Assert.False(Directory.Exists(invalid));
            Assert.Empty(Directory.GetDirectories(root, "*.import-*"));
            await File.WriteAllTextAsync(source, "[client]\nrequired_stamp_cost=300");
            var costError = await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetConfigImport.ImportAsync(source, invalid));
            Assert.Contains("255", costError.Message);
            Assert.False(Directory.Exists(invalid));
            await File.WriteAllBytesAsync(source, [0xff, 0xff]);
            await Assert.ThrowsAsync<DecoderFallbackException>(() => NomadNetConfigImport.ImportAsync(source, invalid));
            await File.WriteAllBytesAsync(source, new byte[NomadNetConfigImport.MaximumConfigBytes + 1]);
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetConfigImport.ImportAsync(source, invalid));
        }
        finally { Directory.Delete(root, true); }
    }

    [Fact]
    public async Task CustomHostingRootsServeConfiguredPagesAndFilesNotDefaultContent()
    {
        var root = CreateDirectory();
        try
        {
            var pages = Path.Combine(root, "custom-pages");
            var files = Path.Combine(root, "custom-files");
            var content = new NomadNetContent(root, pagesPath: pages, filesPath: files);
            await File.WriteAllTextAsync(Path.Combine(pages, "index.mu"), "custom root");
            await File.WriteAllTextAsync(Path.Combine(files, "public.txt"), "custom file");
            var page = new RequestContext("/page/index.mu", null, new byte[16], new byte[16], null, 0);
            Assert.Equal("custom root", Encoding.UTF8.GetString(Assert.IsType<byte[]>(await content.RespondAsync(page, default))));
            Assert.Equal("custom file", Encoding.UTF8.GetString(Assert.IsType<FileResponse>(
                await content.RespondAsync(page with { Path = "/file/public.txt" }, default)).Data));
            Assert.False(Directory.Exists(Path.Combine(root, "storage", "pages")));
        }
        finally { Directory.Delete(root, true); }
    }

    private static string CreateDirectory()
    {
        var path = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomadnet-config-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(path);
        return path;
    }
}
